(async () => {
  const T = await import('/vendor/three/three.module.js'); window.__T = T;
  const base = T.Object3D.prototype.onBeforeRender;
  T.Object3D.prototype.onBeforeRender = function (r, s, c) {
    if (s && s.isScene && s.children && s.children.length > 3) { window.__S = s; window.__CAM = c; window.__R = r; }
    return base.apply(this, arguments);
  };
  window.__NAN = [];
  const cbs = T.BufferGeometry.prototype.computeBoundingSphere;
  T.BufferGeometry.prototype.computeBoundingSphere = function () {
    const r = cbs.apply(this, arguments);
    if (this.boundingSphere && isNaN(this.boundingSphere.radius)) window.__NAN.push(this.name || this.type);
    return r;
  };
  window.__M = {
    find(name) { let f = null; window.__S.traverse(x => { if (x.isMesh && x.name === name) f = x; }); return f; },
    setVisible(name, v) { let n = 0; window.__S.traverse(x => { if (x.isMesh && x.name === name) { x.visible = v; n++; } }); return n; },
    // project a mesh's 4 plane corners to screen px
    box(name) {
      const m = window.__M.find(name), cam = window.__CAM;
      if (!m || !cam) return null;
      const W = 1280, H = 720;
      if (!m.geometry.boundingBox) m.geometry.computeBoundingBox();
      const bb = m.geometry.boundingBox, v = new T.Vector3();
      let x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9;
      for (const cx of [bb.min.x, bb.max.x]) for (const cy of [bb.min.y, bb.max.y]) {
        v.set(cx, cy, 0).applyMatrix4(m.matrixWorld).project(cam);
        const px = (v.x * 0.5 + 0.5) * W, py = (1 - (v.y * 0.5 + 0.5)) * H;
        x0 = Math.min(x0, px); x1 = Math.max(x1, px); y0 = Math.min(y0, py); y1 = Math.max(y1, py);
      }
      const wp = new T.Vector3(); m.getWorldPosition(wp);
      return { name, x0: Math.round(x0), x1: Math.round(x1), y0: Math.round(y0), y1: Math.round(y1),
               world: [+wp.x.toFixed(1), +wp.y.toFixed(1), +wp.z.toFixed(1)],
               aabbY: [+(new T.Box3().setFromObject(m)).min.y.toFixed(2), +(new T.Box3().setFromObject(m)).max.y.toFixed(2)],
               camY: +cam.position.y.toFixed(2), camPos: [+cam.position.x.toFixed(1), +cam.position.z.toFixed(1)] };
    },
    // independent: cast a ray from the camera to a point on the card and report what it hits first
    rayTo(name, u, v) {
      const m = window.__M.find(name), cam = window.__CAM;
      if (!m || !cam) return null;
      if (!m.geometry.boundingBox) m.geometry.computeBoundingBox();
      const bb = m.geometry.boundingBox;
      const p = new T.Vector3(bb.min.x + u * (bb.max.x - bb.min.x), bb.min.y + v * (bb.max.y - bb.min.y), 0).applyMatrix4(m.matrixWorld);
      const dir = p.clone().sub(cam.position).normalize();
      const rc = new T.Raycaster(cam.position.clone(), dir, 0.1, p.distanceTo(cam.position) - 0.5);
