      window.__S.traverse(o => { if (o.isMesh && o.visible && /^hill-|^ground$|^tree-|forestCards/.test(o.name || '')) targets.push(o); });
      const h = rc.intersectObjects(targets, false);
      return { pt: [+p.x.toFixed(1), +p.y.toFixed(1), +p.z.toFixed(1)], blockedBy: h.length ? h[0].object.name : null, at: h.length ? +h[0].distance.toFixed(1) : null };
