      const down = new T.Vector3(0, -1, 0);
      const SKIP = /^(sky|clouds|hill-|forestCards|landmark|water|pond|blobShadows|contactShadows|motes|butterfl|bird|smoke|ripple|sun|moon|star|haze|ui|cursor|lanternGlow)/i;
      const FLY = /(bird|butterfl|mote|smoke|cloud|laundry|washing|glow|duck|-hull|gdepth|gbody|ghull)/i;
      const rows = [], box = new T.Box3(), v = new T.Vector3(), m4 = new T.Matrix4();
