        const gb = o.geometry.boundingBox;
        const push = (mat, tag) => {
          box.copy(gb).applyMatrix4(mat); box.getCenter(v);
          rc.set(new T.Vector3(v.x, 120, v.z), down);
          const h = rc.intersectObject(ground, false); if (!h.length) return;
          rows.push({ n: tag, x: +v.x.toFixed(1), z: +v.z.toFixed(1), gap: +(box.min.y - h[0].point.y).toFixed(3) });
